        if (!path.add(t)) return null;
        for (FType c : tc) {
            List<Set<FType>> sub = coverParts(c, at, path, steps);
            if (sub == null) return null;
            res.addAll(sub);
        }
        path.remove(t);
        return res;
    }
    catch (FortressException ex) {
        return null;
